import json

with open('/workspace/DEMOS.json') as f:
    demos = json.load(f)

d = demos[0]
changed = [(i, inp, out) for i, (inp, out) in enumerate(zip(d['input_examples'], d['output_examples'])) if inp != out]

def find_candidates_v2(inp, out, max_pred=3, max_trans=3):
    if inp == out:
        return [("", "")]

    results = []
    seen = set()

    for start in range(len(inp)):
        for end in range(start + 1, min(start + max_pred + 1, len(inp) + 1)):
            pred = inp[start:end]
            if len(pred) < 1 or len(pred) > max_pred:
                continue

            before = inp[:start]
            after = inp[end:]

            if not out.startswith(before):
                continue

            out_middle = out[len(before):]

            for b_len in range(0, max_trans + 1):
                if len(out_middle) < b_len:
                    continue
                B = out_middle[:b_len]
                rest = out_middle[b_len:]

                if after.replace(pred, B) == rest:
                    key = (pred, B)
                    if key not in seen:
                        seen.add(key)
                        results.append((pred, B))

    return results

# Find candidates for each changed pair in demo 0
for idx, inp, out in changed[:3]:
    cands = find_candidates_v2(inp, out)
    print(f"Pair #{idx}: {repr(inp)} -> {repr(out)}")
    print(f"  Candidates ({len(cands)}):")
    for p, t in cands[:15]:
        test = inp.replace(p, t)
        print(f"    replace('{p}', '{t}'): {repr(test)} {'✓' if test == out else '✗'}")
    print()

