import json
from itertools import product, permutations, combinations

def find_candidates(inp, out, max_pred=3, max_trans=3):
    """Find all (pred, trans) where inp.replace(pred, trans) == out"""
    if inp == out:
        return [("", "")]

    results = []
    seen = set()

    for start in range(len(inp)):
        for end in range(start + 1, min(start + max_pred + 1, len(inp) + 1)):
            pred = inp[start:end]
            if len(pred) < 1 or len(pred) > max_pred:
                continue

            before = inp[:start]
            after = inp[end:]

            if not out.startswith(before):
                continue

            out_middle = out[len(before):]

            for b_len in range(0, max_trans + 1):
                if len(out_middle) < b_len:
                    continue
                B = out_middle[:b_len]
                rest = out_middle[b_len:]

                if after.replace(pred, B) == rest:
                    key = (pred, B)
                    if key not in seen:
                        seen.add(key)
                        results.append((pred, B))

    return results

with open('/workspace/DEMOS.json') as f:
    demos = json.load(f)

d = demos[0]
inputs = d['input_examples']
outputs = d['output_examples']

changed = [(i, inp, out) for i, (inp, out) in enumerate(zip(inputs, outputs)) if inp != out]

# Get candidates for all changed pairs
all_candidates = {}
for idx, inp, out in changed:
    cands = find_candidates(inp, out)
    all_candidates[idx] = cands
    print(f"Pair #{idx}: {repr(inp)} -> {repr(out)} ({len(cands)} candidates)")
    for p, t in cands:
        print(f"  replace('{p}', '{t}')")

print()
# Find unique operations across all pairs
unique_ops = set()
for idx, cands in all_candidates.items():
    for p, t in cands:
        unique_ops.add((p, t))

print(f"Total unique operations: {len(unique_ops)}")
for op in sorted(unique_ops):
    print(f"  replace('{op[0]}', '{op[1]}')")

