import json
from itertools import product, permutations, combinations

def find_candidates(inp, out, max_pred=3, max_trans=3):
    if inp == out:
        return [("", "")]
    results = []
    seen = set()
    for start in range(len(inp)):
        for end in range(start + 1, min(start + max_pred + 1, len(inp) + 1)):
            pred = inp[start:end]
            before = inp[:start]
            after = inp[end:]
            if not out.startswith(before):
                continue
            out_middle = out[len(before):]
            for b_len in range(0, max_trans + 1):
                if len(out_middle) < b_len:
                    continue
                B = out_middle[:b_len]
                rest = out_middle[b_len:]
                if after.replace(pred, B) == rest:
                    key = (pred, B)
                    if key not in seen:
                        seen.add(key)
                        results.append((pred, B))
    return results

def apply_program(program, s):
    """Apply a sequence of replace operations to string s"""
    for pred, trans in program:
        s = s.replace(pred, trans)
    return s

def score_program(program, inputs, outputs):
    """Score a program against all examples"""
    correct = sum(1 for inp, out in zip(inputs, outputs) if apply_program(program, inp) == out)
    return correct / len(inputs)

with open('/workspace/DEMOS.json') as f:
    demos = json.load(f)

# Test on demo 0
d = demos[0]
inputs = d['input_examples']
outputs = d['output_examples']

changed = [(i, inp, out) for i, (inp, out) in enumerate(zip(inputs, outputs)) if inp != out]

# Get candidates for each changed pair
pair_candidates = {}
for idx, inp, out in changed:
    pair_candidates[idx] = [c for c in find_candidates(inp, out) if c[0] != ""]

# Required operations (unique candidates)
required = set()
optional = {}
for idx, cands in pair_candidates.items():
    if len(cands) == 1:
        required.add(cands[0])
    else:
        optional[idx] = cands

print(f"Required: {required}")
print(f"Optional pairs: {list(optional.keys())}")

# Now try all combinations: required + one from each optional pair
if optional:
    # For each optional pair, pick one candidate
    optional_values = list(optional.values())
    all_combinations = product(*optional_values)

    best_prog = None
    best_score = -1

    for combo in all_combinations:
        prog = sorted(required | set(combo))  # deduplicate
        if len(prog) > 5:  # skip programs that are too long
            continue

        # Try different orderings
        for ordering in permutations(prog):
            score = score_program(ordering, inputs, outputs)
            if score > best_score:
                best_score = score
                best_prog = list(ordering)
        if best_score == 1.0:
            break

    print(f"\nBest score: {best_score}")
    print(f"Best program: {best_prog}")

    # Verify
    for inp, out in zip(inputs, outputs):
        result = apply_program(best_prog, inp)
        if result != out:
            print(f"  FAIL: {repr(inp)} -> {repr(result)} (expected {repr(out)})")

    print(f"  All correct: {all(apply_program(best_prog, inp) == out for inp, out in zip(inputs, outputs))}")

