import json
from itertools import product, permutations, combinations

def find_candidates(inp, out, max_pred=3, max_trans=3):
    if inp == out:
        return [("", "")]
    results = []
    seen = set()
    for start in range(len(inp)):
        for end in range(start + 1, min(start + max_pred + 1, len(inp) + 1)):
            pred = inp[start:end]
            before = inp[:start]
            after = inp[end:]
            if not out.startswith(before):
                continue
            out_middle = out[len(before):]
            for b_len in range(0, max_trans + 1):
                if len(out_middle) < b_len:
                    continue
                B = out_middle[:b_len]
                rest = out_middle[b_len:]
                if after.replace(pred, B) == rest:
                    key = (pred, B)
                    if key not in seen:
                        seen.add(key)
                        results.append((pred, B))
    return results

def apply_program(program, s):
    for pred, trans in program:
        s = s.replace(pred, trans)
    return s

def score_program(program, inputs, outputs):
    correct = sum(1 for inp, out in zip(inputs, outputs) if apply_program(program, inp) == out)
    return correct / len(inputs)

def solve_simple(inputs, outputs, max_programs=5):
    changed = [(i, inp, out) for i, (inp, out) in enumerate(zip(inputs, outputs)) if inp != out]

    if not changed:
        return []

    # Get candidates for each changed pair
    pair_candidates = {}
    for idx, inp, out in changed:
        cands = [c for c in find_candidates(inp, out) if c[0] != ""]
        pair_candidates[idx] = cands

    # Required operations (unique candidates)
    required = set()
    optional = {}
    for idx, cands in pair_candidates.items():
        if len(cands) == 1:
            required.add(cands[0])
        else:
            optional[idx] = cands

    # If too many required ops, we need to handle it
    if len(required) > max_programs:
        return None

    # Try all combinations
    best_prog = None
    best_score = -1

    if optional:
        optional_values = list(optional.values())
        all_combos = product(*optional_values)
    else:
        all_combos = [()]

    for combo in all_combos:
        prog = list(required | set(combo))
        if len(prog) > max_programs:
            continue

        # For small sets, try all orderings
        if len(prog) <= 6:
            for ordering in permutations(prog):
                score = score_program(ordering, inputs, outputs)
                if score > best_score:
                    best_score = score
                    best_prog = list(ordering)
        else:
            # For larger sets, try a few orderings
            for _ in range(min(100, factorial(len(prog)))):
                ordering = list(prog)
                for i in range(len(ordering) - 1, 0, -1):
                    j = random.randint(0, i)
                    ordering[i], ordering[j] = ordering[j], ordering[i]
                score = score_program(ordering, inputs, outputs)
                if score > best_score:
                    best_score = score
                    best_prog = ordering

        if best_score == 1.0:
            break

    if best_score == 1.0:
        return best_prog
    return None

