from itertools import product, permutations
import time

def find_candidates(inp, out, max_pred=3, max_trans=3):
    if inp == out:
        return [("", "")]
    results = []
    seen = set()
    for start in range(len(inp)):
        for end in range(start + 1, min(start + max_pred + 1, len(inp) + 1)):
            pred = inp[start:end]
            before = inp[:start]
            after = inp[end:]
            if not out.startswith(before):
                continue
            out_middle = out[len(before):]
            for b_len in range(0, max_trans + 1):
                if len(out_middle) < b_len:
                    continue
                B = out_middle[:b_len]
                rest = out_middle[b_len:]
                if after.replace(pred, B) == rest:
                    key = (pred, B)
                    if key not in seen:
                        seen.add(key)
                        results.append((pred, B))
    return results

def find_partial_candidates(inp, out, max_pred=3, max_trans=3):
    results = []
    if inp == out:
        return results
    seen = set()
    for start in range(len(inp)):
        for end in range(start + 1, min(start + max_pred + 1, len(inp) + 1)):
            pred = inp[start:end]
            for b_len in range(0, max_trans + 1):
                before = inp[:start]
                if out.startswith(before):
                    out_middle = out[len(before):]
                    for bl in range(0, min(len(out_middle) + 1, max_trans + 1)):
                        B = out_middle[:bl]
                        key = (pred, B)
                        if key not in seen:
                            seen.add(key)
                            results.append(key)
    return results

def apply_program(program, s):
    for pred, trans in program:
        s = s.replace(pred, trans)
    return s

def score_program(program, inputs, outputs):
    correct = sum(1 for inp, out in zip(inputs, outputs) if apply_program(program, inp) == out)
    return correct / len(inputs)

def solve_fast(inputs, outputs, max_programs=5, max_time=25):
    changed = [(i, inp, out) for i, (inp, out) in enumerate(zip(inputs, outputs)) if inp != out]
    if not changed:
        return []

    start_time = time.time()

    # Get candidates for each changed pair
    pair_candidates = {}
    for idx, inp, out in changed:
        cands = [c for c in find_candidates(inp, out) if c[0] != ""]
        pair_candidates[idx] = cands

    # Separate into unique, multiple, and missing
    unique_ops = set()
    optional = {}
    for idx, cands in pair_candidates.items():
        if len(cands) == 1:
            unique_ops.add(cands[0])
        elif len(cands) > 1:
            optional[idx] = cands

    # Collect all candidate ops from all sources
    all_candidate_ops = set(unique_ops)

    # Get partial candidates for pairs with no complete candidate
    hard_pairs = {}
    for idx, cands in pair_candidates.items():
        if len(cands) == 0:
            inp, out = changed[idx]
            hard_pairs[idx] = (inp, out)
            partial = find_partial_candidates(inp, out)
            all_candidate_ops.update(partial)

    # Also include all candidates from optional pairs
    for cands in optional.values():
        all_candidate_ops.update(cands)

    # Convert to sorted list for deterministic search
    all_candidate_ops = sorted(all_candidate_ops)

    # Strategy 1: Try unique ops + combinations of optional
    best_prog = []
    best_score = 0

    # Sort unique ops by predicate length (longer first for specificity)
    unique_sorted = sorted(unique_ops, key=lambda x: (-len(x[0]), x))

    # Try permutations of unique ops (up to 5)
    for n in range(1, min(len(unique_sorted) + 1, max_programs + 1)):
        if time.time() - start_time > max_time - 10:
            break
        for ordering in permutations(unique_sorted[:n]):
            prog = list(ordering)
            score = score_program(prog, inputs, outputs)
            if score > best_score:
                best_score = score
                best_prog = prog
            if score == 1.0:
                return prog

    # Strategy 2: Add optional/hard ops greedily
    if best_prog:
        remaining = [op for op in all_candidate_ops if op not in set(best_prog)]

        for step in range(max_programs - len(best_prog)):
            if time.time() - start_time > max_time - 5:
                break
            best_step_prog = None
            best_step_score = best_score

            for op in remaining:
                test_prog = best_prog + [op]
                score = score_program(test_prog, inputs, outputs)
                if score > best_step_score:
                    best_step_score = score
                    best_step_prog = test_prog

            if best_step_prog:
                best_prog = best_step_prog
                best_score = best_step_score
                if best_score == 1.0:
                    return best_prog
            else:
                break

    # Strategy 3: Try all combinations of required + some optional
    if optional:
        opt_keys = sorted(optional.keys())
        opt_values = [optional[k] for k in opt_keys]

        # Limit combinations
        total_combos = 1
        for vals in opt_values:
            total_combos *= len(vals)

        if total_combos <= 10000:
            for combo in product(*opt_values):
                if time.time() - start_time > max_time - 10:
                    break
                prog_set = unique_ops | set(combo)
                prog_list = sorted(prog_set)
                if len(prog_list) > max_programs:
                    continue
                for ordering in permutations(prog_list):
                    score = score_program(list(ordering), inputs, outputs)
                    if score > best_score:
                        best_score = score
                        best_prog = list(ordering)
                    if best_score == 1.0:
                        return best_prog

    # Strategy 4: Try pairs of partial ops for hard pairs + remaining
    if hard_pairs:
        for idx, (inp, out) in hard_pairs.items():
            if best_score >= 1.0:
                break
            partials = find_partial_candidates(inp, out)

            # Try each partial op combined with existing best
            for op in partials:
                if op in set(best_prog):
                    continue
                test_ops = set(best_prog) | {op}
                for ordering in permutations(test_ops):
                    score = score_program(list(ordering), inputs, outputs)
                    if score > best_score:
                        best_score = score
                        best_prog = list(ordering)
                        if best_score == 1.0:
                            return best_prog

            # Try 2 ops together for this hard pair
            for p1_idx in range(len(partials)):
                if best_score >= 1.0:
                    break
                p1, t1 = partials[p1_idx]
                for p2_idx in range(p1_idx + 1, len(partials)):
                    p2, t2 = partials[p2_idx]
                    # Try both orderings
                    for prog in [[(p1,t1), (p2,t2)], [(p2,t2), (p1,t1)]]:
                        result = apply_program(prog, inp)
                        if result == out:
                            other_ops = unique_sorted  # unique ops only
                            combined = sorted(set(prog) | set(other_ops))
                            if len(combined) <= max_programs:
                                for ordering in permutations(combined):
                                    score = score_program(list(ordering), inputs, outputs)
                                    if score > best_score:
                                        best_score = score
                                        best_prog = list(ordering)
                                        if best_score == 1.0:
                                            return best_prog

    # Try permutations of best_prog for final improvement
    for ordering in permutations(best_prog):
        score = score_program(list(ordering), inputs, outputs)
        if score > best_score:
            best_score = score
            best_prog = list(ordering)
            if best_score == 1.0:
                return best_prog

    return best_prog if best_score > 0 else None

# Test on first 20 demos
