                pred = inp[start:end]
                before = inp[:start]
                if out.startswith(before):
                    out_middle = out[len(before):]
                    for bl in range(0, min(len(out_middle) + 1, 4)):
                        B = out_middle[:bl]
                        all_ops.add((pred, B))

