def solve_v9(inputs, outputs, max_programs=5, max_time=30):
    changed_list = [(idx, inp, out) for idx, (inp, out) in enumerate(zip(inputs, outputs)) if inp != out]
    if not changed_list:
        return []

    start_time = time.time()

    pair_candidates = {}
    hard_pairs = {}
    for idx, inp, out in changed_list:
        cands = [c for c in find_candidates(inp, out) if c[0] != ""]
        if cands:
            pair_candidates[idx] = cands
        else:
            hard_pairs[idx] = (inp, out)

    unique_ops = set()
    optional = {}
    for idx, cands in pair_candidates.items():
        if len(cands) == 1:
            unique_ops.add(cands[0])
        elif len(cands) > 1:
            optional[idx] = cands

    # Collect all candidate ops
    all_ops = set(unique_ops)
    for cands in optional.values():
        all_ops.update(cands)

    # Find best 2-op sequences for hard pairs
    hard_seqs = []
    for idx, (inp, out) in hard_pairs.items():
        seq = find_best_2op_sequence(inp, out)
        if seq:
            hard_seqs.append((idx, seq))
            all_ops.add(seq[0])
            all_ops.add(seq[1])

    all_ops = sorted(all_ops)
    unique_sorted = sorted(unique_ops, key=lambda x: (-len(x[0]), x))

    best_prog = []
    best_score = 0

    def update(prog):
        nonlocal best_prog, best_score
        score = score_program(prog, inputs, outputs)
        if score > best_score:
            best_score = score
            best_prog = list(prog)
        return best_score == 1.0

    # Phase 1: Greedy with increasing max_programs
    for max_p in range(max(1, max_programs), min(max_programs + 15, 25)):
        if time.time() - start_time > max_time - 5:
            break

        # Unique ops permutations
        for n in range(1, min(len(unique_sorted) + 1, max_p + 1)):
            if time.time() - start_time > max_time - 5:
                break
            for ordering in permutations(unique_sorted[:n]):
                if update(list(ordering)):
                    return best_prog

        # Greedy add
        if best_prog and len(best_prog) < max_p:
            remaining = [op for op in all_ops if op not in set(best_prog)]
            for step in range(max_p - len(best_prog)):
                best_step = None
                best_step_score = best_score
                for op in remaining:
                    test = best_prog + [op]
                    s = score_program(test, inputs, outputs)
                    if s > best_step_score:
                        best_step_score = s
                        best_step = test
                if best_step:
                    best_prog = best_step
                    best_score = best_step_score
                    if best_score == 1.0:
                        return best_prog
                else:
                    break

        # Optional combinations
        if optional:
            opt_keys = sorted(optional.keys())
            opt_values = [optional[k] for k in opt_keys]
            total = 1
            for vals in opt_values:
                total *= len(vals)
            if total <= 5000 and time.time() - start_time < max_time - 5:
                for combo in product(*opt_values):
                    if time.time() - start_time > max_time - 5:
                        break
                    prog_set = unique_ops | set(combo)
                    prog_list = sorted(prog_set)
                    if len(prog_list) <= max_p:
                        for ordering in permutations(prog_list):
                            if update(list(ordering)):
                                return best_prog

        # Phase 2: Try hard pair 2-op sequences
        if hard_seqs:
            for idx, (p1, t1), (p2, t2) in hard_seqs:
                if time.time() - start_time > max_time - 3:
                    break

                # Try: unique + both hard pair ops
                extra = {(p1,t1), (p2,t2)}
                prog_set = set(unique_sorted) | extra
                prog_list = sorted(prog_set, key=lambda x: (-len(x[0]), x))
                if len(prog_list) <= max_p:
                    if update(prog_list):
                        return best_prog
                    prog_list.reverse()
                    if update(prog_list):
                        return best_prog

                # Try: base prog + both hard pair ops
                if best_prog:
                    prog_set = set(best_prog) | extra
                    prog_list = sorted(prog_set, key=lambda x: (-len(x[0]), x))
                    if len(prog_list) <= max_p:
                        if update(prog_list):
