import json
from itertools import product, permutations
import time

def find_candidates(inp, out, max_pred=3, max_trans=3):
    if inp == out:
        return [("", "")]
    results = []
    seen = set()
    for start in range(len(inp)):
        for end in range(start + 1, min(start + max_pred + 1, len(inp) + 1)):
            pred = inp[start:end]
            before = inp[:start]
            after = inp[end:]
            if not out.startswith(before):
                continue
            out_middle = out[len(before):]
            for b_len in range(0, max_trans + 1):
                if len(out_middle) < b_len:
                    continue
                B = out_middle[:b_len]
                rest = out_middle[b_len:]
                if after.replace(pred, B) == rest:
                    key = (pred, B)
                    if key not in seen:
                        seen.add(key)
                        results.append((pred, B))
    return results

def find_all_2op_sequences(inp, out, max_pred=3, max_trans=3):
    """Find ALL valid 2-op sequences for a pair"""
    results = []
    seen = set()
    for start1 in range(len(inp)):
        for end1 in range(start1 + 1, min(start1 + max_pred + 1, len(inp) + 1)):
            p1 = inp[start1:end1]
            for b_len1 in range(0, max_trans + 1):
                before1 = inp[:start1]
                if not out.startswith(before1):
                    continue
                out_after = out[len(before1):]
                if len(out_after) < b_len1:
                    continue
                t1 = out_after[:b_len1]
                intermediate = inp.replace(p1, t1)
                if intermediate == out:
                    continue
                for start2 in range(len(intermediate)):
                    for end2 in range(start2 + 1, min(start2 + max_pred + 1, len(intermediate) + 1)):
                        p2 = intermediate[start2:end2]
                        before2 = intermediate[:start2]
                        if not out.startswith(before2):
                            continue
                        out_after2 = out[len(before2):]
                        for b_len2 in range(0, max_trans + 1):
                            if len(out_after2) < b_len2:
                                continue
                            t2 = out_after2[:b_len2]
                            key = (p1, t1, p2, t2)
                            if key not in seen:
                                seen.add(key)
                                if inp.replace(p1, t1).replace(p2, t2) == out:
                                    results.append(((p1, t1), (p2, t2)))
    return results

def apply_program(program, s):
    for pred, trans in program:
        s = s.replace(pred, trans)
    return s

def score_program(program, inputs, outputs):
    return sum(1 for inp, out in zip(inputs, outputs) if apply_program(program, inp) == out) / len(inputs)

def solve_v11(inputs, outputs, max_programs=5, max_time=30):
    changed_list = [(idx, inp, out) for idx, (inp, out) in enumerate(zip(inputs, outputs)) if inp != out]
    if not changed_list:
        return []

    start_time = time.time()

    pair_candidates = {}
    hard_pairs = {}
    for idx, inp, out in changed_list:
        cands = [c for c in find_candidates(inp, out) if c[0] != ""]
        if cands:
            pair_candidates[idx] = cands
        else:
            hard_pairs[idx] = (inp, out)

    unique_ops = set()
    optional = {}
    for idx, cands in pair_candidates.items():
        if len(cands) == 1:
            unique_ops.add(cands[0])
        elif len(cands) > 1:
            optional[idx] = cands

    # Collect all candidate operations
    all_ops = set(unique_ops)
    for cands in optional.values():
        all_ops.update(cands)

    # For hard pairs, find all 2-op sequences and add ALL their operations to pool
    hard_seqs = {}
    for idx, (inp, out) in hard_pairs.items():
        seqs = find_all_2op_sequences(inp, out)
        if seqs:
            hard_seqs[idx] = seqs[:30]  # Limit to 30
            for (p1, t1), (p2, t2) in seqs[:30]:
                all_ops.add((p1, t1))
                all_ops.add((p2, t2))

    all_ops = sorted(all_ops)
    unique_sorted = sorted(unique_ops, key=lambda x: (-len(x[0]), x))

    best_prog = []
    best_score = 0

    def update(prog):
        nonlocal best_prog, best_score
        score = score_program(prog, inputs, outputs)
        if score > best_score:
            best_score = score
            best_prog = list(prog)
        return best_score == 1.0

    # Phase 1: Greedy with increasing max_programs
    for max_p in range(max(1, max_programs), min(max_programs + 15, 25)):
        if time.time() - start_time > max_time - 5:
            break

        # Unique ops permutations
        for n in range(1, min(len(unique_sorted) + 1, max_p + 1)):
            if time.time() - start_time > max_time - 5:
                break
            for ordering in permutations(unique_sorted[:n]):
                if update(list(ordering)):
                    return best_prog

        # Greedy add
        if best_prog and len(best_prog) < max_p:
            remaining = [op for op in all_ops if op not in set(best_prog)]
            for step in range(max_p - len(best_prog)):
                best_step = None
                best_step_score = best_score
                for op in remaining:
                    test = best_prog + [op]
                    s = score_program(test, inputs, outputs)
                    if s > best_step_score:
                        best_step_score = s
                        best_step = test
                if best_step:
                    best_prog = best_step
                    best_score = best_step_score
                    if best_score == 1.0:
                        return best_prog
                else:
                    break

        # Optional combinations
        if optional:
            opt_keys = sorted(optional.keys())
            opt_values = [optional[k] for k in opt_keys]
            total = 1
            for vals in opt_values:
                total *= len(vals)
            if total <= 5000 and time.time() - start_time < max_time - 5:
                for combo in product(*opt_values):
                    if time.time() - start_time > max_time - 5:
                        break
                    prog_set = unique_ops | set(combo)
                    prog_list = sorted(prog_set)
                    if len(prog_list) <= max_p:
                        for ordering in permutations(prog_list):
                            if update(list(ordering)):
                                return best_prog

        # Phase 2: Try all 2-op sequences for hard pairs
        if hard_seqs:
            for idx, seqs in hard_seqs.items():
                if time.time() - start_time > max_time - 3:
                    break
                for (p1, t1), (p2, t2) in seqs:
                    # Try: base + both hard ops
                    if best_prog:
                        prog_set = set(best_prog) | {(p1,t1), (p2,t2)}
                        prog_list = sorted(prog_set, key=lambda x: (-len(x[0]), x))
                        if len(prog_list) <= max_p:
                            if update(prog_list):
                                return best_prog
                            # Try all orderings for small programs
                            if len(prog_list) <= 5:
                                for ordering in permutations(prog_list):
                                    if update(list(ordering)):
                                        return best_prog

    # Final: try permutations of best_prog
    if best_prog and len(best_prog) <= 8:
        for ordering in permutations(best_prog):
            if update(list(ordering)):
                return best_prog

    return best_prog if best_score > 0 else None

# Test on first 20 demos
with open('/workspace/DEMOS.json') as f:
    demos = json.load(f)

correct = 0
failed = 0
total_time = 0
for i in range(20):
    d = demos[i]
    inputs = d['input_examples']
    outputs = d['output_examples']
    t0 = time.time()
    prog = solve_v11(inputs, outputs, max_programs=5, max_time=25)
    elapsed = time.time() - t0
    total_time += elapsed

    if prog:
        c = all(apply_program(prog, inp) == out for inp, out in zip(inputs, outputs))
        if c:
            correct += 1
            print(f"Demo {i}: ✓ ({len(prog)} ops, {elapsed:.1f}s)")
        else:
            score = score_program(prog, inputs, outputs)
            failed += 1
            print(f"Demo {i}: partial ({len(prog)} ops, score={score:.3f})")
    else:
        failed += 1
        print(f"Demo {i}: ✗ no solution")

print(f"\nResults: {correct}/20 correct, {failed}/20 failed in {total_time:.1f}s")

